import random

def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']
    weight = max(0.1, 1.0 / (round_num + 2))
    if action == 'cooperate':
        new_reputation = current_reputation + weight
    else:
        new_reputation = current_reputation - weight
    return max(-1.0, min(1.0, new_reputation))

def decide(recipient_reputation, round_num, my_history):
    if recipient_reputation > 0.2:
        return True
    elif recipient_reputation < -0.2:
        return False
    else:
        coop_count = sum(1 for h in my_history if h['action'] == 'cooperate')
        return random.random() < (coop_count / (len(my_history) + 1) if my_history else 0.5)
